import{_ as e,o as a,c as t,Q as o}from"./chunks/framework.b67c47e6.js";const s="/assets/sizes-materials.6e5d501c.svg",f=JSON.parse('{"title":"Sizes and Materials","description":"","frontmatter":{},"headers":[],"relativePath":"guide/stock/index.md","filePath":"guide/stock/index.md","lastUpdated":1790346505000}'),r={name:"guide/stock/index.md"},i=o('<h1 id="sizes-and-materials" tabindex="-1">Sizes and Materials <a class="header-anchor" href="#sizes-and-materials" aria-label="Permalink to &quot;Sizes and Materials&quot;">​</a></h1><p>The <strong>Sizes and Materials</strong> view lets you manage your material catalog — the materials, sizes, and products used across your projects. Open it from <strong>Sizes and Materials</strong> in the company menu, under <em>Constructibles</em>. It used to be called <em>Stock products</em>.</p><nav class="table-of-contents"><ul><li><a href="#catalog-sections">Catalog Sections</a><ul><li><a href="#materials">Materials</a></li><li><a href="#plate-size">Plate Size</a></li><li><a href="#profile-size">Profile Size</a></li><li><a href="#product-plate">Product Plate</a></li><li><a href="#product-profile">Product Profile</a></li></ul></li><li><a href="#managing-catalog-entries">Managing Catalog Entries</a></li><li><a href="#connection-to-other-features">Connection to Other Features</a></li></ul></nav><p><img src="'+s+'" alt="The Sizes and Materials view, with Plate Size open"></p><ol><li><strong>New</strong> adds an entry to the table that is open.</li><li>A plate size is a thickness of a material. The sheet dimensions you buy are products: see <a href="#product-plate">Product Plate</a>.</li></ol><h2 id="catalog-sections" tabindex="-1">Catalog Sections <a class="header-anchor" href="#catalog-sections" aria-label="Permalink to &quot;Catalog Sections&quot;">​</a></h2><p>The view contains five tables, each managing a different part of your material catalog. Each table starts folded: click its title to open it.</p><p>Materials and sizes are also created automatically when your designs are analysed, so most entries appear here without anyone typing them.</p><h3 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h3><p>The base materials used in production. Each material has a <strong>Name</strong>, a <strong>Material Family</strong> (wood, chipboard, gypsum or steel) and an optional <strong>ERP Code</strong>.</p><h3 id="plate-size" tabindex="-1">Plate Size <a class="header-anchor" href="#plate-size" aria-label="Permalink to &quot;Plate Size&quot;">​</a></h3><p>The sheet materials by thickness. Each entry combines a material with a <strong>Thickness</strong>, plus an optional <strong>Finish</strong>, <strong>Comment</strong> and <strong>ERP Code</strong>. Reports and logistics use these to filter plates by size.</p><h3 id="profile-size" tabindex="-1">Profile Size <a class="header-anchor" href="#profile-size" aria-label="Permalink to &quot;Profile Size&quot;">​</a></h3><p>The cross-sections of profile materials (structural elements like studs and beams). Each entry has a <strong>Width</strong> and <strong>Height</strong>, a material, an optional <strong>Finish</strong>, <strong>Comment</strong> and <strong>ERP Code</strong>, and an icon that tells rectangular sections from shaped ones. Whether a section is shaped comes from the design and cannot be changed here.</p><h3 id="product-plate" tabindex="-1">Product Plate <a class="header-anchor" href="#product-plate" aria-label="Permalink to &quot;Product Plate&quot;">​</a></h3><p>The sheets you buy. Each entry has a <strong>Name</strong>, a plate size, and the <strong>Width</strong> and <strong>Length</strong> of the sheet.</p><h3 id="product-profile" tabindex="-1">Product Profile <a class="header-anchor" href="#product-profile" aria-label="Permalink to &quot;Product Profile&quot;">​</a></h3><p>The bars you buy. Each entry has a <strong>Name</strong>, a profile size, and the <strong>Length</strong> of the bar.</p><h2 id="managing-catalog-entries" tabindex="-1">Managing Catalog Entries <a class="header-anchor" href="#managing-catalog-entries" aria-label="Permalink to &quot;Managing Catalog Entries&quot;">​</a></h2><p>For each table, you can:</p><ul><li><strong>Create</strong> — Press <strong>New</strong> in the table&#39;s header to add an entry.</li><li><strong>Edit</strong> — Press the pencil on a row to change it.</li><li><strong>Delete</strong> — Press the bin on a row to remove it. You are asked to confirm.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Deleting a material or size that is referenced by existing designs or reports may cause issues. Only remove entries that are no longer needed.</p></div><h2 id="connection-to-other-features" tabindex="-1">Connection to Other Features <a class="header-anchor" href="#connection-to-other-features" aria-label="Permalink to &quot;Connection to Other Features&quot;">​</a></h2><ul><li>The material catalog feeds into <a href="/guide/logistics/">Logistics</a> for tracking material availability.</li><li><a href="/guide/reports/">Reports</a> use material and size data for Bills of Materials and filtering options.</li><li>Machine file generation uses material properties to determine processing parameters.</li></ul>',24),n=[i];function l(c,h,d,g,p,u){return a(),t("div",null,n)}const b=e(r,[["render",l]]);export{f as __pageData,b as default};
